void PluginMain(PA_long32 selector, PA_PluginParameters params)
{
	try
	{
		PA_long32 pProcNum = selector;
		sLONG_PTR *pResult = (sLONG_PTR *)params->fResult;
		PackagePtr pParams = (PackagePtr)params->fParameters;

		CommandDispatcher(pProcNum, pResult, pParams);
	}
	catch(...)
	{

	}
}

static void _CommandDispatcher (PA_long32 pProcNum, sLONG_PTR *pResult, PackagePtr pParams);

void CommandDispatcher (PA_long32 pProcNum, sLONG_PTR *pResult, PackagePtr pParams)
{
	//every command returns a longint error code; if one throws (only std::bad_alloc
	//from the parameter classes is realistic), report it instead of returning 0
	try
	{
		_CommandDispatcher(pProcNum, pResult, pParams);
	}
	catch(...)
	{
		if(pProcNum > 0){
			C_LONGINT returnValue;
#if VERSIONMAC
			returnValue.setIntValue(ENOMEM);
#else
			returnValue.setIntValue(ERROR_NOT_ENOUGH_MEMORY);
#endif
			returnValue.setReturn(pResult);
		}
	}
}

static void _CommandDispatcher (PA_long32 pProcNum, sLONG_PTR *pResult, PackagePtr pParams)
{
	switch(pProcNum)
	{
// --- Files and Folders

		case 1 :
			PATH_Get_creation_date(pResult, pParams);
			break;

		case 2 :
			PATH_Set_modification_date(pResult, pParams);
			break;

		case 3 :
			PATH_Get_modification_date(pResult, pParams);
			break;

		case 4 :
			PATH_Set_creation_date(pResult, pParams);
			break;

		case 5 :
			PATH_Get_access_date(pResult, pParams);
			break;

		case 6 :
			PATH_Set_access_date(pResult, pParams);
			break;

		case 7 :
			PATH_Get_hidden(pResult, pParams);
			break;

		case 8 :
			PATH_Set_hidden(pResult, pParams);
			break;

	}
}

